#!/bin/bash
# Self-installing offline package bundle for @APP_NAME@
# Generated by Deb2Bundle (deb2bundle.sh) -- do not edit by hand.
#
#   ./file.dxe              graphical installer (zenity) if available, else terminal
#   ./file.dxe --terminal   force the terminal installer
#   ./file.dxe --yes        skip the welcome/confirmation screen
#   ./file.dxe --info       show what is inside
#   ./file.dxe --extract D  unpack the .deb files + repo index into directory D
#   ./file.dxe --force      skip the Debian release check

APP_NAME='@APP_NAME@'
APP_ID='@APP_ID@'
MAIN_PKGS='@MAIN_PKGS@'
BUILT_FOR_RELEASE='@RELEASE@'
BUILT_FOR_ARCH='@ARCH@'
BUILT_FOR_FOREIGN_ARCHES='@FOREIGN_ARCHES@'
PAYLOAD_SHA256='@SHA256@'

# Metadata for the welcome screen (version, description, icon, launcher...)
@META@

shopt -u patsub_replacement 2>/dev/null || true

export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
SELF=$(readlink -f -- "$0")
LOGFILE="/var/log/${APP_ID}-install.log"

MODE=ui FORCE=0 TERMONLY=0 PAUSE=0 ASSUME_YES=0 EXDIR=""

# --------------------------------------------------------------- payload ---
payload_start() {
    awk '/^__PAYLOAD_BELOW__$/ { print NR + 1; exit }' "$SELF"
}
payload() {
    tail -n +"$(payload_start)" "$SELF"
}

# -------------------------------------------------------- worker (root) ---
say() {
    printf '%s\n#%s\n' "$1" "$2"
}

worker() {
    export DEBIAN_FRONTEND=noninteractive
    export NEEDRESTART_MODE=a
    export APT_LISTCHANGES_FRONTEND=none
    export LC_ALL=C

    if (( EUID != 0 )); then
        echo "RESULT:fail:installer must run as root"
        return 1
    fi

    : > "$LOGFILE"
    chmod 644 "$LOGFILE"

    local WORK
    WORK=$(mktemp -d "/tmp/${APP_ID}.XXXXXX") ||
        { echo "RESULT:fail:cannot create temp dir"; return 1; }

    chmod 755 "$WORK"
    trap 'rm -rf "$WORK"' EXIT

    fail() {
        echo "RESULT:fail:$1"
        exit 1
    }

    say 2 "Verifying installer integrity"

    local sum
    sum=$(payload | sha256sum | cut -d' ' -f1)

    [[ "$sum" == "$PAYLOAD_SHA256" ]] ||
        fail "installer file is corrupt (checksum mismatch)"

    say 6 "Unpacking packages"

    payload | tar -x -C "$WORK" >>"$LOGFILE" 2>&1 ||
        fail "could not unpack payload (disk full?)"

    chmod -R a+rX "$WORK"

    # Enable foreign architectures BEFORE apt-get update.
    # For Wine on amd64 this enables the i386 package architecture.
    if [[ -n "$BUILT_FOR_FOREIGN_ARCHES" ]]; then
        say 8 "Enabling foreign package architectures"

        local arch
        local -a FOREIGN_ARCH_ARRAY=()

        IFS=',' read -r -a FOREIGN_ARCH_ARRAY \
            <<< "$BUILT_FOR_FOREIGN_ARCHES"

        for arch in "${FOREIGN_ARCH_ARRAY[@]}"; do
            [[ -n "$arch" ]] || continue

            if [[ "$arch" == "$BUILT_FOR_ARCH" ]]; then
                continue
            fi

            if ! dpkg --print-foreign-architectures |
                grep -Fxq "$arch"; then
                dpkg --add-architecture "$arch" >>"$LOGFILE" 2>&1 ||
                    fail "could not enable architecture $arch"
            fi
        done
    fi

    say 10 "Preparing local package repository"

    mkdir -p "$WORK/lists/partial" "$WORK/cache/archives/partial"

    # This is a flat, local repository containing Packages.gz and debs/.
    printf 'deb [trusted=yes] file:%s ./\n' "$WORK" \
        > "$WORK/local.list"

    local APT_OPTS=(
        -o "Dir::Etc::SourceList=$WORK/local.list"
        -o Dir::Etc::SourceParts=/dev/null
        -o "Dir::State::Lists=$WORK/lists"
        -o "Dir::Cache=$WORK/cache"
        -o APT::Sandbox::User=root
        -o Acquire::Check-Date=false
        -o Acquire::Languages=none
    )

    apt-get "${APT_OPTS[@]}" update >>"$LOGFILE" 2>&1 </dev/null ||
        fail "could not read bundled package index (see $LOGFILE)"

    say 14 "Installing $APP_NAME"

    local rc

    # MAIN_PKGS is intentionally split into individual package arguments.
    # This allows package specifications such as wine32:i386.
    apt-get "${APT_OPTS[@]}" -y --no-install-recommends \
        -o Dpkg::Options::=--force-confdef \
        -o Dpkg::Options::=--force-confold \
        -o APT::Status-Fd=3 \
        install $MAIN_PKGS 3>&1 >>"$LOGFILE" 2>&1 </dev/null |
    while IFS=: read -r kind pkg pct msg; do
        local n=${pct%%.*}
        [[ "$n" =~ ^[0-9]+$ ]] || continue

        case "$kind" in
            dlstatus)
                say $(( 14 + n * 16 / 100 )) "Preparing packages"
                ;;
            pmstatus)
                say $(( 30 + n * 69 / 100 )) "$msg"
                ;;
        esac
    done

    rc=${PIPESTATUS[0]}

    (( rc == 0 )) ||
        fail "package installation failed (apt exit code $rc). Log: $LOGFILE"

    say 100 "Done"
    echo "RESULT:ok"
}

# ------------------------------------------------------------ UI helpers ---
USE_GUI=false

term_draw() {
    local pct=$1 msg=$2 w=40 f

    (( pct > 100 )) && pct=100
    f=$(( pct * w / 100 ))

    printf '\r\033[K[%s%s] %3d%%  %s' \
        "$(printf '%*s' "$f" '' | tr ' ' '#')" \
        "$(printf '%*s' $(( w - f )) '' | tr ' ' '.')" \
        "$pct" "$msg"
}

# ------------------------------------------------- welcome / finish screens ---
esc() {
    local s=$1
    s=${s//&/&amp;}; s=${s//</&lt;}; s=${s//>/&gt;}
    printf '%s' "$s"
}

human_kb() {
    awk -v k="${1:-0}" 'BEGIN {
        if (k >= 1048576) printf "%.1f GB", k / 1048576
        else if (k >= 1024) printf "%.0f MB", k / 1024
        else printf "%d KB", k }'
}

ICON_FILE="" ZICON=()
setup_icon() {
    $USE_GUI && [[ -n $ICON_B64 ]] || return 0
    ICON_FILE=$(mktemp --suffix=.png)
    if printf '%s' "$ICON_B64" | base64 -d >"$ICON_FILE" 2>/dev/null; then
        ZICON=(--window-icon="$ICON_FILE")
    else
        rm -f "$ICON_FILE"; ICON_FILE=""
    fi
    trap 'rm -f "$ICON_FILE"' EXIT
}

# Returns 0 to continue with the installation, 1 if the user cancelled.
welcome() {
    (( ASSUME_YES )) && return 0
    local nl=$'\n' t size a
    size=$(human_kb "$TOTAL_KB")

    if $USE_GUI; then
        t="<span size='xx-large' weight='bold'>$(esc "$APP_NAME")</span>"
        [[ -n $APP_VERSION ]] && t+="${nl}<span foreground='#888888'>Version $(esc "$APP_VERSION")</span>"
        t+="${nl}${nl}"
        [[ -n $APP_SUMMARY ]] && t+="<b>$(esc "$APP_SUMMARY")</b>${nl}${nl}"
        [[ -n $APP_DESC ]]    && t+="$(esc "$APP_DESC")${nl}${nl}"
        [[ -n $APP_URL ]]     && t+="Website: $(esc "$APP_URL")${nl}${nl}"
        t+="This installer contains <b>$N_PKGS</b> package(s)"
        (( TOTAL_KB > 0 )) && t+=", up to <b>$size</b> once installed"
        t+=". Packages already on your system are skipped.${nl}${nl}"
        t+="Click <b>Install</b> to continue. You will be asked for an administrator password."
        zenity --question --title="$APP_NAME Setup" --width=520 "${ZICON[@]}" \
            --icon-name=system-software-install \
            --ok-label="Install" --cancel-label="Cancel" --text="$t"
        return
    fi

    echo "$APP_NAME${APP_VERSION:+ $APP_VERSION}"
    [[ -n $APP_SUMMARY ]] && echo "$APP_SUMMARY"
    [[ -n $APP_DESC ]] && { echo; echo "$APP_DESC"; }
    echo; echo "Packages: $N_PKGS$( (( TOTAL_KB > 0 )) && echo " (up to $size once installed)")"
    if [[ -t 0 ]]; then
        read -rp "Install now? [Y/n] " a
        [[ $a != [nN]* ]]
    else
        return 0
    fi
}

# Sets LAUNCH_EXEC to a command that starts the app ("" if none can be found).
find_launcher() {
    LAUNCH_EXEC=""
    if [[ -n $LAUNCH_CMD ]]; then LAUNCH_EXEC=$LAUNCH_CMD; return; fi
    local pkg f
    for pkg in $MAIN_PKGS; do
        pkg=${pkg%%:*}
        while IFS= read -r f; do
            [[ $f == /usr/share/applications/*.desktop && -r $f ]] || continue
            grep -qi '^NoDisplay=true' "$f" && continue
            grep -qi '^Terminal=true' "$f" && continue
            LAUNCH_EXEC=$(grep -m1 '^Exec=' "$f" | sed 's/^Exec=//; s/ *%[a-zA-Z]//g')
            [[ -n $LAUNCH_EXEC ]] && return
        done < <(dpkg -L "$pkg" 2>/dev/null)
    done
}

launch_app() {
    ( setsid bash -c "$LAUNCH_EXEC" >/dev/null 2>&1 </dev/null & )
}

finish_ok() {
    local nl=$'\n'
    find_launcher
    if $USE_GUI; then
        local t="<span size='x-large' weight='bold'>$(esc "$APP_NAME") was installed successfully.</span>"
        if [[ -n $LAUNCH_EXEC ]]; then
            if zenity --question --title="$APP_NAME Setup" --width=420 "${ZICON[@]}" \
                   --icon-name=system-software-install \
                   --ok-label="Launch $APP_NAME" --cancel-label="Exit" \
                   --text="${t}${nl}${nl}Would you like to start it now?"; then
                launch_app
            fi
        else
            zenity --info --title="$APP_NAME Setup" --width=420 "${ZICON[@]}" \
                --ok-label="Exit" --text="$t"
        fi
    else
        echo "$APP_NAME was installed successfully."
        if [[ -n $LAUNCH_EXEC && -t 0 ]]; then
            local a; read -rp "Launch $APP_NAME now? [y/N] " a
            [[ $a == [yY]* ]] && launch_app
        fi
    fi
}

finish_fail() {
    if $USE_GUI; then
        if zenity --question --no-markup --title="$APP_NAME Setup" --width=440 "${ZICON[@]}" \
               --icon-name=dialog-error --ok-label="Show log" --cancel-label="Close" \
               --text="Installation failed: $1"; then
            tail -n 200 "$LOGFILE" 2>/dev/null |
                zenity --text-info --title="Installation log" --width=760 --height=480 "${ZICON[@]}"
        fi
    else
        echo "Installation failed: $1" >&2
    fi
}

finish_cancelled() {
    local m="Installation was cancelled or administrator access was not granted."
    if $USE_GUI; then
        zenity --warning --no-markup --title="$APP_NAME Setup" "${ZICON[@]}" --text="$m"
    else
        echo "$m" >&2
    fi
}

fatal() {
    if $USE_GUI; then
        zenity --error --no-markup \
            --title="$APP_NAME installer" --text="$1"
    else
        echo "ERROR: $1" >&2
    fi
    exit 1
}

preflight() {
    local arch rel

    arch=$(dpkg --print-architecture 2>/dev/null)

    [[ "$arch" == "$BUILT_FOR_ARCH" ]] ||
        fatal "This installer is for $BUILT_FOR_ARCH systems; this machine is ${arch:-unknown}."

    rel=$(. /etc/os-release 2>/dev/null; echo "${VERSION_CODENAME:-unknown}")

    if [[ "$rel" != "$BUILT_FOR_RELEASE" && "$FORCE" != 1 ]]; then
        fatal "This installer was built for Debian '$BUILT_FOR_RELEASE' but this system is '$rel'. Packages from a different release can break your system. Run with --force to override."
    fi

    command -v apt-get >/dev/null ||
        fatal "apt-get not found; is this a Debian system?"
}

# ------------------------------------------------------------- elevation ---
user_can_sudo() {
    command -v sudo >/dev/null &&
        id -nG | tr ' ' '\n' | grep -qx -e sudo -e admin
}

ask_password_and_run() {
    local worker=(bash "$SELF" --worker)
    local pw who attempt inner

    inner=$(printf '%q ' "${worker[@]}")

    if user_can_sudo; then
        who="your"
    else
        who="the administrator (root)"
    fi

    for attempt in 1 2 3; do
        pw=$(zenity --password \
            --title="Enter $who password to install $APP_NAME" 2>/dev/null) ||
            return 1

        if user_can_sudo; then
            if printf '%s\n' "$pw" |
                sudo -S -k -p '' true 2>/dev/null; then
                printf '%s\n' "$pw" |
                    sudo -S -p '' "${worker[@]}"
                return
            fi
        else
            if { sleep 1; printf '%s\n' "$pw"; } |
                script -qec "su root -c true" /dev/null \
                    >/dev/null 2>&1; then
                { sleep 1; printf '%s\n' "$pw"; } |
                    script -qec "su root -c $(printf '%q' "$inner")" /dev/null
                return
            fi
        fi

        zenity --error --no-markup \
            --text="Incorrect password. Please try again." 2>/dev/null
    done

    return 1
}

run_privileged() {
    local worker=(bash "$SELF" --worker)
    local rc

    if (( EUID == 0 )); then
        "${worker[@]}"
        return
    fi

    if $USE_GUI; then
        if user_can_sudo && command -v pkexec >/dev/null; then
            pkexec "${worker[@]}"
            rc=$?
            (( rc == 127 )) || return "$rc"
        fi
        ask_password_and_run
    else
        if user_can_sudo; then
            sudo "${worker[@]}"
        else
            su root -c "$(printf '%q ' "${worker[@]}")"
        fi
    fi
}

# --------------------------------------------------------------- main UI ---
run_ui() {
    local line pct=0 msg="Starting" T="" ZPID=""
    RESULT=""

    trap '' PIPE

    if $USE_GUI; then
        T=$(mktemp -d)
        mkfifo "$T/p"

        zenity --progress --title="Installing $APP_NAME" "${ZICON[@]}" \
            --text="Preparing..." --percentage=0 \
            --auto-close --no-cancel --no-markup --width=420 \
            <"$T/p" &
        ZPID=$!

        exec 4>"$T/p"
    else
        echo "Installing $APP_NAME (log: $LOGFILE)"
    fi

    while IFS= read -r line; do
        line=${line%$'\r'}

        if [[ "$line" == RESULT:* ]]; then
            RESULT=$line
        elif [[ "$line" == '#'* ]]; then
            msg=${line#\#}
            if $USE_GUI; then
                printf '#%s\n' "$msg" >&4
            else
                term_draw "$pct" "$msg"
            fi
        elif [[ "$line" =~ ^[0-9]+$ ]]; then
            pct=$line
            if $USE_GUI; then
                printf '%s\n' "$pct" >&4
            else
                term_draw "$pct" "$msg"
            fi
        fi
    done < <(run_privileged)

    if $USE_GUI; then
        exec 4>&-
        sleep 0.3
        kill "$ZPID" 2>/dev/null
        wait "$ZPID" 2>/dev/null
        rm -rf "$T"
    else
        echo
    fi

    case $RESULT in
        RESULT:ok)     finish_ok; return 0 ;;
        RESULT:fail:*) finish_fail "${RESULT#RESULT:fail:}"; return 1 ;;
        *)             finish_cancelled; return 1 ;;
    esac
}

main() {
    while (( $# )); do
        case $1 in
            --worker)   MODE=worker ;;
            --terminal) TERMONLY=1 ;;
            --pause)    PAUSE=1 ;;
            --force)    FORCE=1 ;;
            --yes)      ASSUME_YES=1 ;;
            --info)     MODE=info ;;
            --extract)
                MODE=extract
                EXDIR=${2:?--extract needs a directory}
                shift
                ;;
            -h|--help)
                sed -n '2,11p' "$SELF" | sed 's/^# \{0,1\}//'
                return 0
                ;;
            *)
                echo "Unknown option: $1" >&2
                return 2
                ;;
        esac
        shift
    done

    case $MODE in
        worker)
            worker
            return
            ;;
        info)
            echo "$APP_NAME${APP_VERSION:+ $APP_VERSION} (Debian $BUILT_FOR_RELEASE / $BUILT_FOR_ARCH)"
            [[ -n $APP_SUMMARY ]] && echo "$APP_SUMMARY"
            if [[ -n "$BUILT_FOR_FOREIGN_ARCHES" ]]; then
                echo "Foreign architectures: $BUILT_FOR_FOREIGN_ARCHES"
            fi
            echo "Installs: $MAIN_PKGS"
            echo "Bundled packages:"
            payload | tar -t | grep '\.deb$' | sed 's|.*/|  |'
            return
            ;;
        extract)
            mkdir -p "$EXDIR" && payload | tar -x -C "$EXDIR"
            return
            ;;
    esac

    if (( TERMONLY == 0 )) &&
        [[ -n ${DISPLAY:-}${WAYLAND_DISPLAY:-} ]]; then
        if command -v zenity >/dev/null; then
            USE_GUI=true
        elif [[ ! -t 0 && ! -t 1 ]] &&
            command -v x-terminal-emulator >/dev/null; then
            exec x-terminal-emulator -e "$SELF" --terminal --pause
        fi
    fi

    setup_icon
    preflight
    welcome || return 0
    run_ui
    local rc=$?

    if (( PAUSE )); then
        read -rp "Press Enter to close this window..." _
    fi

    return "$rc"
}

main "$@"
exit $?

__PAYLOAD_BELOW__
